catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    g_form.clearValue('key_vault_name');
    g_form.clearOptions('key_vault_name');
    g_form.setMandatory('key_vault_name', false);
    g_form.setDisplay('key_vault_name', false);
    var certificate_category = g_form.getValue("certificate_category");
    var CA = g_form.getValue('certificate_authority');
    var serverCAs = ['AppViewX', 'DigiCert', 'Microsoft Enterprise', 'Entrust', 'Ejbca', 'GoDaddy', 'Amazon', 'Comodo Certificate Manager', 'GlobalSign', 'GlobalSignMSSL', 'Trustwave', 'HydrantID', 'SwissSign', 'Microsoft Standalone'];
    var clientCAs = ['DigiCert', 'Microsoft Enterprise', 'Entrust', 'HydrantID', 'SwissSign'];
    var codeSigningCAs = ['Microsoft Enterprise', 'HydrantID'];
    var csr_input_method = g_form.getValue('csr_input_method');
    if (csr_input_method === 'Manual') {
        if (
            (certificate_category === "Server" && serverCAs.includes(CA)) ||
            (certificate_category === "Client" && clientCAs.includes(CA)) ||
            (certificate_category === "Code Signing" && codeSigningCAs.includes(CA))
        ) {
            g_form.setDisplay("device_details", true);
            g_form.setDisplay("endpoint", true);
        } else {
            g_form.setDisplay("device_details", false);
            g_form.setDisplay("endpoint", false);
        }
    } else {
        g_form.setDisplay("device_details", false);
        g_form.setDisplay("endpoint", false);
    }


    //Type appropriate comment here, and begin script below

}
